from calendar import monthrange
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext


def amortize(principal: str, annual_rate_percent: str, months: int, start_date: str) -> list[dict]:
    if not isinstance(principal, str):
        raise ValueError("invalid principal")
    try:
        principal_dec = Decimal(principal)
    except (InvalidOperation, ValueError, OverflowError):
        raise ValueError("invalid principal") from None
    if not principal_dec.is_finite() or principal_dec <= Decimal("0") or principal_dec.as_tuple().exponent < -2:
        raise ValueError("invalid principal")
    if not isinstance(annual_rate_percent, str):
        raise ValueError("invalid annual_rate_percent")
    try:
        rate_dec = Decimal(annual_rate_percent)
    except (InvalidOperation, ValueError, OverflowError):
        raise ValueError("invalid annual_rate_percent") from None
    if not rate_dec.is_finite() or rate_dec < Decimal("0") or rate_dec > Decimal("100"):
        raise ValueError("invalid annual_rate_percent")
    if isinstance(months, bool) or not isinstance(months, int):
        raise ValueError("invalid months")
    if months < 1 or months > 360:
        raise ValueError("invalid months")
    if not isinstance(start_date, str):
        raise ValueError("invalid start_date")
    if len(start_date) != 10 or start_date[4] != "-" or start_date[7] != "-":
        raise ValueError("invalid start_date")
    year_part = start_date[0:4]
    month_part = start_date[5:7]
    day_part = start_date[8:10]
    if not (year_part.isascii() and year_part.isdigit() and month_part.isascii() and month_part.isdigit() and day_part.isascii() and day_part.isdigit()):
        raise ValueError("invalid start_date")
    try:
        start = date(int(year_part), int(month_part), int(day_part))
    except ValueError:
        raise ValueError("invalid start_date") from None
    cent = Decimal("0.01")
    with localcontext() as ctx:
        ctx.prec = 50
        monthly_rate = rate_dec / Decimal("1200")
        principal_q = principal_dec.quantize(cent, rounding=ROUND_HALF_UP)
        if monthly_rate == Decimal("0"):
            level_payment = (principal_q / Decimal(months)).quantize(cent, rounding=ROUND_HALF_UP)
        else:
            level_payment = (principal_q * monthly_rate / (Decimal("1") - (Decimal("1") + monthly_rate) ** (-months))).quantize(cent, rounding=ROUND_HALF_UP)
        schedule = []
        balance = principal_q
        anchor_day = start.day
        for n in range(1, months + 1):
            month_offset = start.month - 1 + n
            payment_year = start.year + month_offset // 12
            payment_month = month_offset % 12 + 1
            payment_day = min(anchor_day, monthrange(payment_year, payment_month)[1])
            payment_date = date(payment_year, payment_month, payment_day).isoformat()
            interest = (balance * monthly_rate).quantize(cent, rounding=ROUND_HALF_UP)
            if n == months:
                principal_part = balance.quantize(cent, rounding=ROUND_HALF_UP)
                payment = (balance + interest).quantize(cent, rounding=ROUND_HALF_UP)
                new_balance = Decimal("0.00")
            else:
                payment = level_payment
                principal_part = (payment - interest).quantize(cent, rounding=ROUND_HALF_UP)
                new_balance = (balance - principal_part).quantize(cent, rounding=ROUND_HALF_UP)
            schedule.append({"n": n, "date": payment_date, "payment": payment, "interest": interest, "principal": principal_part, "balance": new_balance})
            balance = new_balance
        return schedule


def total_interest(schedule) -> Decimal:
    with localcontext() as ctx:
        ctx.prec = 50
        total = Decimal("0.00")
        for row in schedule:
            total += row["interest"]
        return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
